/** Operations in the `consoleProjects` service. */
export class ConsoleProjectsService {
  readonly #client: Client

  constructor(client: Client) {
    this.#client = client
  }

  /**
   * Creates a project in `provisioning`; it turns `active` once its database schema exists. Owners and
   * developers; fails with `org_not_active` while the org is deleting.
   */
  create(orgId: string, body: CreateProjectRequest, options?: RequestOptions): Promise<Project> {
    return this.#client.request<Project>(
      { method: 'POST', path: `/v1/console/orgs/${encodeURIComponent(orgId)}/projects`, body },
      options,
    )
  }

  /**
   * Deletes the project: it stops being served at once and is purged after the grace period, with its
   * data, keys, platforms, and users. Owners only.
   */
  delete(options?: RequestOptions): Promise<Project> {
    return this.#client.request<Project>({ method: 'DELETE', path: '/v1/console/project' }, options)
  }

  /** Gets the project named by `X-Orvano-Project`, in any state. */
  get(options?: RequestOptions): Promise<Project> {
    return this.#client.request<Project>({ method: 'GET', path: '/v1/console/project' }, options)
  }

  /** Lists an org's projects, deleting ones included. */
  list(
    orgId: string,
    query?: { cursor?: string | undefined; limit?: number | undefined },
    options?: RequestOptions,
  ): Promise<ProjectPage> {
    return this.#client.request<ProjectPage>(
      { method: 'GET', path: `/v1/console/orgs/${encodeURIComponent(orgId)}/projects`, query },
      options,
    )
  }

  /** Every item of `list`, walking all pages: `for await (const item of ...)`. */
  listAll(
    orgId: string,
    query?: { limit?: number | undefined },
    options?: RequestOptions,
  ): AsyncGenerator<Project> {
    return paginate((cursor) => this.list(orgId, { ...query, cursor }, options))
  }

  /** Restores a deleting project before its purge; it passes through `provisioning`. Owners only. */
  restore(options?: RequestOptions): Promise<Project> {
    return this.#client.request<Project>(
      { method: 'POST', path: '/v1/console/project/restore' },
      options,
    )
  }

  /** Retries provisioning a `failed` project. Owners and developers. */
  retryProvisioning(options?: RequestOptions): Promise<Project> {
    return this.#client.request<Project>(
      { method: 'POST', path: '/v1/console/project/retry-provisioning' },
      options,
    )
  }

  /** Retries the purge of a deleting project whose purge ran out of attempts. Owners and install admins. */
  retryPurge(options?: RequestOptions): Promise<Project> {
    return this.#client.request<Project>(
      { method: 'POST', path: '/v1/console/project/retry-purge' },
      options,
    )
  }

  /** Renames the project. Owners and developers. */
  update(body: UpdateProjectRequest, options?: RequestOptions): Promise<Project> {
    return this.#client.request<Project>(
      { method: 'PATCH', path: '/v1/console/project', body },
      options,
    )
  }
}

/** Operations in the `consoleSmtp` service. */
export class ConsoleSmtpService {
  readonly #client: Client

  constructor(client: Client) {
    this.#client = client
  }

  /**
   * Deletes the project's own SMTP settings, so it sends through the install's, if any. Owners and developers.
   * Answers 204 also when nothing is stored.
   */
  delete(options?: RequestOptions): Promise<void> {
    return this.#client.request<undefined>(
      { method: 'DELETE', path: '/v1/console/project/email/smtp', idempotent: true },
      options,
    )
  }

  /** Gets the SMTP settings of the project named by `X-Orvano-Project`, and whose settings it sends through. */
  get(options?: RequestOptions): Promise<ProjectSmtp> {
    return this.#client.request<ProjectSmtp>(
      { method: 'GET', path: '/v1/console/project/email/smtp' },
      options,
    )
  }

  /**
   * Sends a test email to your own console email through the given settings, saved or not, and stores nothing.
   * Owners and developers. Waits at most 20 seconds and never retries; a failure answers `smtp_unreachable`,
   * `smtp_tls_failed`, `smtp_auth_failed`, `smtp_rejected`, or `smtp_timeout`.
   */
  test(body: SmtpSettingsInput, options?: RequestOptions): Promise<EmailTestResult> {
    return this.#client.request<EmailTestResult>(
      { method: 'POST', path: '/v1/console/project/email/smtp/test', body },
      options,
    )
  }

  /**
   * Saves the project's own SMTP settings, replacing any stored ones. Owners and developers. Fails with
   * `smtp_host_not_allowed` when the host is, or resolves to, a private network address.
   */
  update(body: SmtpSettingsInput, options?: RequestOptions): Promise<SmtpSettings> {
    return this.#client.request<SmtpSettings>(
      { method: 'PUT', path: '/v1/console/project/email/smtp', body, idempotent: true },
      options,
    )
  }
}

/** Operations in the `consoleUsers` service. */
export class ConsoleUsersService {
  readonly #client: Client

  constructor(client: Client) {
    this.#client = client
  }

  /** Blocks a user: ends every session and refuses sign in. Blocking a blocked user changes nothing. */
  block(userId: string, options?: RequestOptions): Promise<User> {
    return this.#client.request<User>(
      {
        method: 'POST',
        path: `/v1/console/project/users/${encodeURIComponent(userId)}/block`,
        idempotent: true,
      },
      options,
    )
  }

  /** Creates a user with an email and password. It does not sign them in. */
  create(body: CreateUserRequest, options?: RequestOptions): Promise<User> {
    return this.#client.request<User>(
      { method: 'POST', path: '/v1/console/project/users', body },
      options,
    )
  }

  /** Emails a user a password reset link. Owners and developers. */
  createRecovery(
    userId: string,
    body: CreateUserRecoveryRequest,
    options?: RequestOptions,
  ): Promise<void> {
    return this.#client.request<undefined>(
      {
        method: 'POST',
        path: `/v1/console/project/users/${encodeURIComponent(userId)}/recovery`,
        body,
      },
      options,
    )
  }

  /** Emails a user a link that verifies their email. Owners and developers. */
  createVerification(
    userId: string,
    body: CreateUserVerificationRequest,
    options?: RequestOptions,
  ): Promise<void> {
    return this.#client.request<undefined>(
      {
        method: 'POST',
        path: `/v1/console/project/users/${encodeURIComponent(userId)}/verification`,
        body,
      },
      options,
    )
  }

  /** Deletes a user with their password and sessions. It can't be undone. */
  delete(userId: string, options?: RequestOptions): Promise<void> {
    return this.#client.request<undefined>(
      { method: 'DELETE', path: `/v1/console/project/users/${encodeURIComponent(userId)}` },
      options,
    )
  }

  /** Unlinks one of a user's identities; owners and developers only. The user's last way to sign in can't be removed. */
  deleteIdentity(userId: string, identityId: string, options?: RequestOptions): Promise<void> {
    return this.#client.request<undefined>(
      {
        method: 'DELETE',
        path: `/v1/console/project/users/${encodeURIComponent(userId)}/identities/${encodeURIComponent(identityId)}`,
      },
      options,
    )
  }

  /** Removes one of a user's passkeys. Sessions stay. Owners and developers. */
  deletePasskey(userId: string, passkeyId: string, options?: RequestOptions): Promise<void> {
    return this.#client.request<undefined>(
      {
        method: 'DELETE',
        path: `/v1/console/project/users/${encodeURIComponent(userId)}/passkeys/${encodeURIComponent(passkeyId)}`,
      },
      options,
    )
  }

  /** Ends one session of a user. */
  deleteSession(userId: string, sessionId: string, options?: RequestOptions): Promise<void> {
    return this.#client.request<undefined>(
      {
        method: 'DELETE',
        path: `/v1/console/project/users/${encodeURIComponent(userId)}/sessions/${encodeURIComponent(sessionId)}`,
      },
      options,
    )
  }

  /** Ends every session of a user. */
  deleteSessions(userId: string, options?: RequestOptions): Promise<void> {
    return this.#client.request<undefined>(
      {
        method: 'DELETE',
        path: `/v1/console/project/users/${encodeURIComponent(userId)}/sessions`,
      },
      options,
    )
  }

  /** Gets a user. */
  get(userId: string, options?: RequestOptions): Promise<User> {
    return this.#client.request<User>(
      { method: 'GET', path: `/v1/console/project/users/${encodeURIComponent(userId)}` },
      options,
    )
  }

  /**
   * The MFA state of a user of the project named by `X-Orvano-Project`: whether sign in asks them for a second factor,
   * their recovery codes left, and their passkeys. Every role.
   */
  getMfa(userId: string, options?: RequestOptions): Promise<MfaStatus> {
    return this.#client.request<MfaStatus>(
      { method: 'GET', path: `/v1/console/project/users/${encodeURIComponent(userId)}/mfa` },
      options,
    )
  }

  /** Lists the users of the project named by `X-Orvano-Project`, newest first. Every role. */
  list(
    query?: {
      email?: string | undefined
      status?: string | undefined
      createdAfter?: string | undefined
      createdBefore?: string | undefined
      emailVerified?: boolean | undefined
      mfa?: string | undefined
      cursor?: string | undefined
      limit?: number | undefined
    },
    options?: RequestOptions,
  ): Promise<UserPage> {
    return this.#client.request<UserPage>(
      { method: 'GET', path: '/v1/console/project/users', query },
      options,
    )
  }

  /** Every item of `list`, walking all pages: `for await (const item of ...)`. */
  listAll(
    query?: {
      email?: string | undefined
      status?: string | undefined
      createdAfter?: string | undefined
      createdBefore?: string | undefined
      emailVerified?: boolean | undefined
      mfa?: string | undefined
      limit?: number | undefined
    },
    options?: RequestOptions,
  ): AsyncGenerator<User> {
    return paginate((cursor) => this.list({ ...query, cursor }, options))
  }

  /** Lists a user's identities, oldest first. */
  listIdentities(userId: string, options?: RequestOptions): Promise<IdentityList> {
    return this.#client.request<IdentityList>(
      { method: 'GET', path: `/v1/console/project/users/${encodeURIComponent(userId)}/identities` },
      options,
    )
  }

  /** Lists a user's passkeys, oldest first, including inactive ones. Every role. */
  listPasskeys(userId: string, options?: RequestOptions): Promise<PasskeyList> {
    return this.#client.request<PasskeyList>(
      { method: 'GET', path: `/v1/console/project/users/${encodeURIComponent(userId)}/passkeys` },
      options,
    )
  }

  /** Lists a user's active sessions, newest first. `current` is always false. */
  listSessions(
    userId: string,
    query?: { cursor?: string | undefined; limit?: number | undefined },
    options?: RequestOptions,
  ): Promise<SessionPage> {
    return this.#client.request<SessionPage>(
      {
        method: 'GET',
        path: `/v1/console/project/users/${encodeURIComponent(userId)}/sessions`,
        query,
      },
      options,
    )
  }

  /** Every item of `listSessions`, walking all pages: `for await (const item of ...)`. */
  listSessionsAll(
    userId: string,
    query?: { limit?: number | undefined },
    options?: RequestOptions,
  ): AsyncGenerator<Session> {
    return paginate((cursor) => this.listSessions(userId, { ...query, cursor }, options))
  }

  /**
   * Turns MFA off for a user of the project named by `X-Orvano-Project`: deletes their authenticator app and recovery
   * codes and ends all their sessions. Passkeys stay. Owners and developers.
   */
  resetMfa(userId: string, options?: RequestOptions): Promise<void> {
    return this.#client.request<undefined>(
      {
        method: 'POST',
        path: `/v1/console/project/users/${encodeURIComponent(userId)}/mfa/reset`,
        idempotent: true,
      },
      options,
    )
  }

  /** Unblocks a user so they can sign in again. Their old sessions stay ended. */
  unblock(userId: string, options?: RequestOptions): Promise<User> {
    return this.#client.request<User>(
      {
        method: 'POST',
        path: `/v1/console/project/users/${encodeURIComponent(userId)}/unblock`,
        idempotent: true,
      },
      options,
    )
  }

  /** Changes a user's email at once, without a confirmation email. Owners and developers. */
  updateEmail(
    userId: string,
    body: UpdateUserEmailRequest,
    options?: RequestOptions,
  ): Promise<User> {
    return this.#client.request<User>(
      {
        method: 'PUT',
        path: `/v1/console/project/users/${encodeURIComponent(userId)}/email`,
        body,
        idempotent: true,
      },
      options,
    )
  }

  /** Marks a user's email verified or unverified. Owners and developers. */
  updateEmailVerification(
    userId: string,
    body: UpdateEmailVerificationRequest,
    options?: RequestOptions,
  ): Promise<User> {
    return this.#client.request<User>(
      {
        method: 'PUT',
        path: `/v1/console/project/users/${encodeURIComponent(userId)}/email-verification`,
        body,
        idempotent: true,
      },
      options,
    )
  }
}

/** Every console service on one object. Only the Orvano console uses it. */
export class Orvano {
  /** The client every service sends through. */
  readonly client: Client
  /** Operations in the `consoleAccount` service. */
  readonly consoleAccount: ConsoleAccountService
  /** Operations in the `consoleApiKeys` service. */
  readonly consoleApiKeys: ConsoleApiKeysService
  /** Operations in the `consoleAuthKeys` service. */
  readonly consoleAuthKeys: ConsoleAuthKeysService
  /** Operations in the `consoleAuthMethods` service. */
  readonly consoleAuthMethods: ConsoleAuthMethodsService
  /** Operations in the `consoleAuthProviders` service. */
  readonly consoleAuthProviders: ConsoleAuthProvidersService
  /** Operations in the `consoleEmailTemplates` service. */
  readonly consoleEmailTemplates: ConsoleEmailTemplatesService
  /** Operations in the `consoleEmails` service. */
  readonly consoleEmails: ConsoleEmailsService
  /** Operations in the `consoleInstall` service. */
  readonly consoleInstall: ConsoleInstallService
  /** Operations in the `consoleInvitations` service. */
  readonly consoleInvitations: ConsoleInvitationsService
  /** Operations in the `consoleMembers` service. */
  readonly consoleMembers: ConsoleMembersService
  /** Operations in the `consoleOrgs` service. */
  readonly consoleOrgs: ConsoleOrgsService
  /** Operations in the `consolePlatforms` service. */
  readonly consolePlatforms: ConsolePlatformsService
  /** Operations in the `consoleProjects` service. */
  readonly consoleProjects: ConsoleProjectsService
  /** Operations in the `consoleSmtp` service. */
  readonly consoleSmtp: ConsoleSmtpService
  /** Operations in the `consoleUsers` service. */
  readonly consoleUsers: ConsoleUsersService

  constructor(client: Client) {
    this.client = client
    this.consoleAccount = new ConsoleAccountService(client)
    this.consoleApiKeys = new ConsoleApiKeysService(client)
    this.consoleAuthKeys = new ConsoleAuthKeysService(client)
    this.consoleAuthMethods = new ConsoleAuthMethodsService(client)
    this.consoleAuthProviders = new ConsoleAuthProvidersService(client)
    this.consoleEmailTemplates = new ConsoleEmailTemplatesService(client)
    this.consoleEmails = new ConsoleEmailsService(client)
    this.consoleInstall = new ConsoleInstallService(client)
    this.consoleInvitations = new ConsoleInvitationsService(client)
    this.consoleMembers = new ConsoleMembersService(client)
    this.consoleOrgs = new ConsoleOrgsService(client)
    this.consolePlatforms = new ConsolePlatformsService(client)
    this.consoleProjects = new ConsoleProjectsService(client)
    this.consoleSmtp = new ConsoleSmtpService(client)
    this.consoleUsers = new ConsoleUsersService(client)
  }
}
